+// Sum every line at full integer-cent value first, then apply the percentage
+// discount to that subtotal and round exactly once. Rounding per line (the
+// previous behaviour) rounds away each fractional cent and inflates totals on
+// multi-line receipts: two 1-cent lines at 50% became 1 + 1 = 2 instead of 1.
+export function totalCents(lines, discountPercent) {
+  const subtotal = lines.reduce((sum, line) => sum + line.cents * line.quantity, 0);
+  return Math.round(subtotal * (1 - discountPercent / 100));
+}

