+// Shared path policy for key handles: a key must be a non-empty relative path
+// with no parent-directory ('..') segments. No trimming or normalization is
+// performed, so values such as 'a/..b' or '//x' keep their existing behavior.
+export function assertSafeKey(value) {
+  if (typeof value !== 'string' || !value || value.startsWith('/') || value.split('/').includes('..')) throw new TypeError('unsafe key');
+  return value;
+}
