+/**
+ * Slice `items` into a one-based page.
+ *
+ * @param {ArrayLike<unknown>} items Source collection. Never mutated.
+ * @param {number} page One-based page number; a positive integer.
+ * @param {number} pageSize Page length; a positive integer.
+ * @returns {{items: unknown[], total: number, pageCount: number}} A fresh array
+ *   holding the requested page (a shallow copy of the source elements).
+ * @throws {RangeError} If `page` or `pageSize` is not a positive integer.
+ */
+export function paginate(items, page, pageSize) {
+  if (!Array.isArray(items)) {
+    throw new TypeError('paginate(items): items must be an array');
+  }
+  if (!Number.isInteger(page) || page < 1) {
+    throw new RangeError(`paginate(page): page must be a positive integer, received ${String(page)}`);
+  }
+  if (!Number.isInteger(pageSize) || pageSize < 1) {
+    throw new RangeError(`paginate(pageSize): pageSize must be a positive integer, received ${String(pageSize)}`);
+  }
+
+  const total = items.length;
+  const pageCount = Math.ceil(total / pageSize);
+  const start = (page - 1) * pageSize;
+  // Array.prototype.slice copies, so callers cannot mutate the input through
+  // the result, and it clamps automatically for pages past the end.
+  const pageItems = items.slice(start, start + pageSize);
+
+  return { items: pageItems, total, pageCount };
+}

